def count_zeros(Q_str):
    return Q_str.count('0')

def calculate_Q(k, N):
    # M is R_k, the number consisting of k ones
    M_str = '1' * k
    M = int(M_str)
    Q = M // N
    return str(Q)

N_list = [2, 3, 5, 7]
results = {}

for N in N_list:
    results[N] = {}
    for k in range(1, 11):
        Q_str = calculate_Q(k, N)
        A = count_zeros(Q_str)
        results[N][k] = A
        print(f"N={N}, k={k}: Q={Q_str}, A={A}")

print("\nSummary of max A found using M=R_k for k=1 to 10:")
for N, data in results.items():
    max_A = max(data.values())
    print(f"N={N}: Max A found = {max_A}")

